const API="https://had-instant-coupons-license.trycloudflare.com";
const MAX_BYTES=2000*1000*1000,allowed=new Set(["wav","flac","m4a"]);
const input=document.querySelector("#audio-file"),zone=document.querySelector("#drop-zone"),result=document.querySelector("#file-result"),error=document.querySelector("#upload-error"),nameEl=document.querySelector("#file-name"),metaEl=document.querySelector("#file-meta"),preview=document.querySelector("#preview-player"),audio=document.querySelector("#audio-preview"),previewStatus=document.querySelector("#preview-status"),uploadButton=document.querySelector("#upload-button"),progress=document.querySelector("#upload-progress"),fill=document.querySelector("#progress-fill"),percent=document.querySelector("#progress-percent"),progressText=document.querySelector("#progress-text");
const analyzeButton=document.querySelector("#analyze-button"),analysisStatus=document.querySelector("#analysis-status"),analysisState=document.querySelector("#analysis-state"),analysisText=document.querySelector("#analysis-text");
const trackResults=document.querySelector("#track-results"),trackCount=document.querySelector("#track-count"),trackList=document.querySelector("#track-list");
const waveformPanel=document.querySelector("#waveform-panel"),waveformWrap=document.querySelector("#waveform-wrap"),waveformCanvas=document.querySelector("#waveform-canvas"),waveformTime=document.querySelector("#waveform-time");
let objectUrl=null,selectedFile=null,uploadedFileId=null,activeTrackEnd=null,activePlayButton=null,lastAnalysis=null;
function setProgress(value,text){const p=Math.max(0,Math.min(100,value));fill.style.width=p+"%";percent.textContent=Math.floor(p)+"%";progressText.textContent=text}
function showFile(file){const ext=(file.name.split(".").pop()||"").toLowerCase();let message="";
if(!allowed.has(ext))message="รองรับเฉพาะ WAV, FLAC และ ALAC (.m4a)";else if(file.size>MAX_BYTES)message="ไฟล์ใหญ่เกิน 2,000 MB";
error.hidden=!message;error.textContent=message;result.hidden=Boolean(message);progress.hidden=true;uploadButton.disabled=Boolean(message);
if(message){selectedFile=null;input.value="";preview.style.display="none";audio.removeAttribute("src");audio.load();return}
selectedFile=file;uploadedFileId=null;activeTrackEnd=null;lastAnalysis=null;waveformPanel.hidden=true;trackResults.hidden=true;trackList.replaceChildren();analyzeButton.disabled=true;analysisStatus.hidden=true;uploadButton.disabled=false;uploadButton.textContent="Upload to Modify";nameEl.textContent=file.name;metaEl.textContent=(file.size/1000000).toFixed(2)+" MB · "+ext.toUpperCase();
if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl=URL.createObjectURL(file);audio.src=objectUrl;audio.load();preview.style.display="block";previewStatus.textContent="พร้อมเล่นจากไฟล์ในอุปกรณ์โดยตรง";
}
input.addEventListener("change",()=>input.files[0]&&showFile(input.files[0]));
["dragenter","dragover"].forEach(t=>zone.addEventListener(t,e=>{e.preventDefault();zone.classList.add("is-dragging")}));
["dragleave","drop"].forEach(t=>zone.addEventListener(t,e=>{e.preventDefault();zone.classList.remove("is-dragging")}));
zone.addEventListener("drop",e=>{const f=e.dataTransfer.files[0];if(f)showFile(f)});
async function jsonPost(url,data,headers={}){const r=await fetch(API+url,{method:"POST",headers:{"Content-Type":"application/json",...headers},body:JSON.stringify(data)});const j=await r.json();if(!r.ok)throw new Error(j.error||("HTTP "+r.status));return j}
uploadButton.addEventListener("click",async()=>{if(!selectedFile)return;uploadButton.disabled=true;progress.hidden=false;setProgress(0,"กำลังสร้าง Upload session…");
try{const init=await jsonPost("/upload/init",{name:selectedFile.name,size:selectedFile.size});const chunkSize=init.chunkSize;let sent=0,index=0;
while(sent<selectedFile.size){const end=Math.min(sent+chunkSize,selectedFile.size),blob=selectedFile.slice(sent,end);const r=await fetch(API+"/upload/chunk",{method:"POST",headers:{"Content-Type":"application/octet-stream","X-Upload-Id":init.uploadId,"X-Chunk-Index":String(index)},body:blob});const j=await r.json();if(!r.ok)throw new Error(j.error||("HTTP "+r.status));sent=end;index++;setProgress(sent/selectedFile.size*100,"ส่งแล้ว "+(sent/1000000).toFixed(1)+" / "+(selectedFile.size/1000000).toFixed(1)+" MB")}
const done=await jsonPost("/upload/complete",{uploadId:init.uploadId});uploadedFileId=done.fileId;setProgress(100,"UPLOAD COMPLETE · "+done.name+" · พร้อมสำหรับ Analyze");uploadButton.textContent="Uploaded to Modify";analyzeButton.disabled=false;
}catch(e){error.hidden=false;error.textContent="Upload failed: "+e.message;setProgress(0,"Upload ไม่สำเร็จ");uploadButton.disabled=false}
});
audio.addEventListener("loadedmetadata",()=>{const s=Math.floor(audio.duration||0),m=Math.floor(s/60),ss=String(s%60).padStart(2,"0");previewStatus.textContent="Duration "+m+":"+ss+" · Local playback"});
audio.addEventListener("error",()=>previewStatus.textContent="Browser ไม่สามารถเล่น codec ของไฟล์นี้ได้");
window.addEventListener("beforeunload",()=>{if(objectUrl)URL.revokeObjectURL(objectUrl)});
analyzeButton.addEventListener("click",async()=>{if(!uploadedFileId)return;analyzeButton.disabled=true;analysisStatus.hidden=false;analysisState.textContent="ANALYZING…";analysisText.textContent="Analyze V2 กำลังประมวลผลบนเครื่อง Modify";error.hidden=true;const started=performance.now();
try{const data=await jsonPost("/analyze",{fileId:uploadedFileId});const elapsed=(performance.now()-started)/1000;analysisState.textContent="ANALYZE COMPLETE";analysisText.textContent=data.detections.length+" detections · "+(data.duration/60).toFixed(2)+" min · "+elapsed.toFixed(1)+" s";lastAnalysis=data;renderWaveform(data);renderTracks(data);analyzeButton.textContent="Re-analyze";analyzeButton.disabled=false;window.lastAnalysis=data}
catch(e){analysisState.textContent="ANALYZE FAILED";analysisText.textContent=e.message;analyzeButton.disabled=false}
});
function formatTime(seconds){seconds=Math.max(0,Number(seconds)||0);const h=Math.floor(seconds/3600),m=Math.floor(seconds%3600/60),s=Math.floor(seconds%60);return h?String(h).padStart(2,"0")+":"+String(m).padStart(2,"0")+":"+String(s).padStart(2,"0"):String(m).padStart(2,"0")+":"+String(s).padStart(2,"0")}
function stopTrackPlayback(){activeTrackEnd=null;if(activePlayButton){activePlayButton.classList.remove("is-playing");activePlayButton.textContent="Play";activePlayButton=null}}
function renderTracks(data){const boundaries=data.detections.map(d=>Number(d.time)).filter(t=>Number.isFinite(t)&&t>0&&t<data.duration).sort((a,b)=>a-b),starts=[0,...boundaries],ends=[...boundaries,data.duration];trackList.replaceChildren();starts.forEach((start,i)=>{const row=document.createElement("div");row.className="track-row";const title=document.createElement("strong");title.textContent="Track "+String(i+1).padStart(2,"0");const time=document.createElement("span");time.className="track-time";time.textContent=formatTime(start)+" → "+formatTime(ends[i]);const play=document.createElement("button");play.type="button";play.className="track-play";play.textContent="Play";play.addEventListener("click",()=>{stopTrackPlayback();audio.currentTime=start;activeTrackEnd=ends[i];activePlayButton=play;play.classList.add("is-playing");play.textContent="Playing";audio.play().catch(()=>stopTrackPlayback())});row.append(title,time,play);trackList.append(row)});trackCount.textContent=starts.length+" Tracks";trackResults.hidden=false}
audio.addEventListener("timeupdate",()=>{if(activeTrackEnd!==null&&audio.currentTime>=activeTrackEnd-.05){audio.pause();audio.currentTime=activeTrackEnd;stopTrackPlayback()}});
audio.addEventListener("pause",()=>{if(activeTrackEnd!==null&&audio.currentTime<activeTrackEnd-.05)stopTrackPlayback()});
function renderWaveform(data){const mins=data.waveform?.minimum||[],maxs=data.waveform?.maximum||[];if(!mins.length||mins.length!==maxs.length)return;const dpr=Math.min(window.devicePixelRatio||1,2),w=Math.max(320,waveformWrap.clientWidth),h=waveformWrap.clientHeight;waveformCanvas.width=Math.round(w*dpr);waveformCanvas.height=Math.round(h*dpr);const c=waveformCanvas.getContext("2d");c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,w,h);c.strokeStyle="#8f969b";c.lineWidth=1;c.beginPath();for(let i=0;i<mins.length;i++){const x=i/(mins.length-1)*w,y1=h/2-Math.max(-1,Math.min(1,maxs[i]))*(h*.43),y2=h/2-Math.max(-1,Math.min(1,mins[i]))*(h*.43);c.moveTo(x,y1);c.lineTo(x,y2)}c.stroke();c.strokeStyle="#d5a94e";c.lineWidth=1;data.detections.forEach(d=>{const x=d.time/data.duration*w;c.beginPath();c.moveTo(x,0);c.lineTo(x,h);c.stroke()});waveformPanel.hidden=false}
waveformCanvas.addEventListener("pointerdown",e=>{if(!lastAnalysis)return;const r=waveformCanvas.getBoundingClientRect(),ratio=Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),t=ratio*lastAnalysis.duration;stopTrackPlayback();audio.currentTime=t;waveformTime.textContent=formatTime(t)});
audio.addEventListener("timeupdate",()=>{if(lastAnalysis)waveformTime.textContent=formatTime(audio.currentTime)});
window.addEventListener("resize",()=>{if(lastAnalysis)renderWaveform(lastAnalysis)});
